 static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;string parent=Path.GetDirectoryName(path).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(path));}
 static Material Mat(string name,Color color,float metallic=0){var m=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(m)return m;m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",.25f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
