 static Mesh Ring(int sides,float outer,float inner,float length){var v=new List<Vector3>();var t=new List<int>();Vector3 P(int i,float radius,float x){float a=i*2*Mathf.PI/sides;return new Vector3(x,Mathf.Cos(a)*radius,Mathf.Sin(a)*radius);}void Q(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int n=v.Count;v.AddRange(new[]{a,b,c,d});t.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}for(int i=0;i<sides;i++){Q(P(i,outer,-length/2),P(i+1,outer,-length/2),P(i+1,outer,length/2),P(i,outer,length/2));Q(P(i,inner,length/2),P(i+1,inner,length/2),P(i+1,inner,-length/2),P(i,inner,-length/2));Q(P(i,outer,length/2),P(i+1,outer,length/2),P(i+1,inner,length/2),P(i,inner,length/2));Q(P(i,inner,-length/2),P(i+1,inner,-length/2),P(i+1,outer,-length/2),P(i,outer,-length/2));}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.RecalculateNormals();return mesh;}
