 static Mesh Bake(Transform root){var materials=new[]{paint,steel,dark,amber};var groups=new List<Mesh>();var final=new CombineInstance[4];for(int i=0;i<4;i++){var list=new List<CombineInstance>();foreach(var part in chunks)if(part.GetComponent<Renderer>().sharedMaterial==materials[i])list.Add(new CombineInstance{mesh=part.GetComponent<MeshFilter>().sharedMesh,transform=root.worldToLocalMatrix*part.transform.localToWorldMatrix});var m=new Mesh();m.CombineMeshes(list.ToArray(),true,true);groups.Add(m);final[i]=new CombineInstance{mesh=m,transform=Matrix4x4.identity};}var result=new Mesh{name="ScrapDumpTruck_LowPoly"};result.CombineMeshes(final,false,true);result.RecalculateBounds();foreach(var m in groups)Object.DestroyImmediate(m);return result;}
