  Box(r,"BedFloor",new Vector3(0,1.55f,-1.3f),new Vector3(2.55f,.25f,6.05f),amber);Box(r,"Headboard",new Vector3(0,2.65f,1.65f),new Vector3(2.7f,2.15f,.18f),paint);Box(r,"Tailgate",new Vector3(0,2.45f,-4.36f),new Vector3(2.65f,1.6f,.16f),paint);
  for(int side=-1;side<=1;side+=2){Box(r,"BedWall",new Vector3(side*1.29f,2.45f,-1.3f),new Vector3(.16f,1.6f,6.05f),paint);Box(r,"TopRail",new Vector3(side*1.29f,3.28f,-1.3f),new Vector3(.23f,.14f,6.12f),steel);for(int j=0;j<5;j++)Box(r,"SideRib",new Vector3(side*1.4f,2.45f,-3.8f+j*1.25f),new Vector3(.15f,1.65f,.14f),amber);Box(r,"Mudguard",new Vector3(side*1.12f,1.24f,-2.8f),new Vector3(.6f,.12f,2.9f),dark);}
  var tire=Ring(12,.57f,.26f,.34f);var hub=Ring(12,.27f,.03f,.36f);foreach(float z in new[]{3.25f,.45f,-2.15f,-3.65f})for(int side=-1;side<=1;side+=2){Tube(r,"Tire",new Vector3(side*1.11f,.57f,z),tire,dark);Tube(r,"Hub",new Vector3(side*1.12f,.57f,z),hub,steel);}
  // Fixed-seed scrap pile: all cargo is merged into the same static mesh.
  var rng=new System.Random(428);float Rand(float lo,float hi){return lo+(hi-lo)*(float)rng.NextDouble();}
  for(int i=0;i<23;i++){Vector3 pos=new Vector3(Rand(-.2f,.2f),Rand(2.45f,3.3f),Rand(-3.25f,.6f));Box(r,"ScrapPlate",pos,new Vector3(Rand(.55f,1.15f),.09f,Rand(.7f,1.6f)),i%3==0?amber:steel);chunks[chunks.Count-1].transform.localRotation=Quaternion.Euler(Rand(-35,35),Rand(0,180),Rand(-28,28));}
  for(int i=0;i<7;i++){var anchor=new Vector3(Rand(-.25f,.25f),Rand(2.7f,3.25f),Rand(-3.3f,.7f));var rotation=Quaternion.Euler(Rand(-20,20),Rand(0,180),Rand(-20,20));foreach(float y in new[]{-.16f,.16f}){Box(r,"ScrapBeamFlange",anchor+rotation*new Vector3(0,y,0),new Vector3(.26f,.06f,1.4f),i%2==0?amber:steel);chunks[chunks.Count-1].transform.localRotation=rotation;}Box(r,"ScrapBeamWeb",anchor,new Vector3(.06f,.32f,1.4f),steel);chunks[chunks.Count-1].transform.localRotation=rotation;}
  var pipe=Ring(10,.2f,.14f,1.2f);for(int i=0;i<3;i++){Tube(r,"ScrapPipe",new Vector3(-.4f+i*.4f,3.35f,-2.3f+i*.65f),pipe,amber);chunks[chunks.Count-1].transform.localRotation=Quaternion.Euler(0,15+i*30,10);}
  var mesh=Bake(r);string meshPath=Root+"/ScrapDumpTruck.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(existing){EditorUtility.CopySerialized(mesh,existing);Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,meshPath);foreach(var chunk in chunks)Object.DestroyImmediate(chunk);chunks.Clear();Object.DestroyImmediate(tire);Object.DestroyImmediate(hub);Object.DestroyImmediate(pipe);root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=new[]{paint,steel,dark,amber};var collider=root.AddComponent<BoxCollider>();collider.center=mesh.bounds.center;collider.size=new Vector3(2.8f,mesh.bounds.size.y,mesh.bounds.size.z);var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/ScrapDumpTruck.prefab");Object.DestroyImmediate(root);
  Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);var instance=(GameObject)PrefabUtility.InstantiatePrefab(prefab);instance.transform.rotation=Quaternion.Euler(0,-20,0);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.name="PreviewGround";floor.transform.position=new Vector3(0,-.1f,0);floor.transform.localScale=new Vector3(120,.2f,120);floor.GetComponent<Renderer>().sharedMaterial=steel;var camera=Camera.main;camera.transform.position=new Vector3(14,10,16);camera.transform.LookAt(new Vector3(0,1.7f,0));camera.fieldOfView=35;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.25f,.34f,.42f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=2;sun.transform.rotation=Quaternion.Euler(45,-30,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.68f,.72f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_ScrapDumpTruck.unity");
